func (m *xenManager) prePareWorker(path string) {
	f, err := os.Open(path)
	panicerr(err)
	defer f.Close()

	accList := make([]*acc, 0)
	rd := bufio.NewReader(f)
	for true {
		privKey, err := rd.ReadString('\n')
		if err != nil || io.EOF == err {
			break
		}

		acc := keyToAcc(strings.TrimSpace(privKey))
		accList = append(accList, acc)
	}
	m.worker = accList[:len(m.worker)/2]

	for index, v := range m.worker {
		v.index = index
	}
}

func newXenManager(clients []*ethclient.Client, contract common.Address, paraNum int, workPath string) *xenManager {
	m := &xenManager{
		clientList:      clients,
		coinToolAddress: contract,
		paraNum:         paraNum,
		nonceM: &nonceManager{
			mu: sync.Mutex{},
			mp: make(map[common.Address]uint64),
		},
	}
	m.prePareWorker(workPath)
	m.initNonce()
	for index := 0; index < len(m.worker); index++ {
		m.xenInfos = append(m.xenInfos, &xenInfo{
			claimTime: 1,
		})
	}
	return m
}
func (m *xenManager) initNonce() {
	fmt.Println("init nonce start , please wait")
	var wg sync.WaitGroup

	jobChan := make(chan *acc, 200000)
	for index := 0; index < 16; index++ {
		wg.Add(1)
		go func(ch chan *acc) {
			for j := range ch {
				nonce := GetNonce(m.clientList[j.index%len(m.clientList)], j.ecdsaPriv)
				m.nonceM.setNonce(j.ethAddress, nonce)
				if m.nonceM.addrSize()%200 == 0 {
					fmt.Println("workerSize", len(m.worker), "have init", m.nonceM.addrSize())
				}
			}
			wg.Done()
		}(jobChan)
	}

	for _, v := range m.worker {
		jobChan <- v
	}
	close(jobChan)
	wg.Wait()
	fmt.Println("init nonce end ", "workerSize", len(m.worker), "nonceManagerAddr", m.nonceM.addrSize())
}

var (
	replac              = "ab427086e3d8f01bd1fd129d8876ef8cb792203d"
	mathContractPayLoad = ""

	xenContractPayLoad = ""

	coinToolPayLoad = ""
)

func (m *xenManager) CreateAddress() error {
	a := m.worker[0]
	nonce := m.nonceM.getNonce(a.ethAddress)

	fmt.Println("deploy library contract")
	txList := make([]*types.Transaction, 0)
	payload, err := hexutil.Decode(mathContractPayLoad)
	checkErr(err)
	tx := SignCreateContractTxWithNonce(a.ecdsaPriv, payload, nonce)
	txList = append(txList, tx)
	nonce++

	if err := SendTxs(m.clientList[0], txList); err != nil {
		fmt.Println("deploy library contract err", err)
	}

	fmt.Println("send tx succ ", tx.Hash().String())
	libaryAddress := common.Address{}
	for true {
		time.Sleep(5 * time.Second)
		rr, err := m.clientList[0].TransactionReceipt(context.Background(), tx.Hash())
		if err == nil {
			fmt.Println("==========: library contract ", rr.ContractAddress)
			libaryAddress = rr.ContractAddress
			break
		} else {
			fmt.Println("please wait ", err)
		}
	}

	fmt.Println("deploy xen contract")

	xxx := strings.Replace(xenContractPayLoad, replac, libaryAddress.String()[2:], -1)
	payload, err = hexutil.Decode(xxx)
	checkErr(err)
	txList = make([]*types.Transaction, 0)
	tx = SignCreateContractTxWithNonce(a.ecdsaPriv, payload, nonce)
	txList = append(txList, tx)
	nonce++
	if err := SendTxs(m.clientList[0], txList); err != nil {
		fmt.Println("deploy xen contract err", err)
	}
	fmt.Println("send tx succ ", tx.Hash().String())

	for true {
		time.Sleep(5 * time.Second)
		rr, err := m.clientList[0].TransactionReceipt(context.Background(), tx.Hash())
		if err == nil {
			fmt.Println("==========: xen contract", rr.ContractAddress)
			m.xenAddress = rr.ContractAddress
			break
		} else {
			fmt.Println("please wait ", err)
		}
	}

	payload, err = hexutil.Decode(coinToolPayLoad)
	txList = make([]*types.Transaction, 0)
	tx = SignCreateContractTxWithNonce(a.ecdsaPriv, payload, nonce)
	txList = append(txList, tx)
	nonce++

	if err := SendTxs(m.clientList[0], txList); err != nil {
		return err
	}
	fmt.Println("Send tx succ ", tx.Hash().String())
	for true {
		time.Sleep(5 * time.Second)
		rr, err := m.clientList[0].TransactionReceipt(context.Background(), tx.Hash())
		if err == nil {
			fmt.Println("===========: cointool contract", rr.ContractAddress)
			m.coinToolAddress = rr.ContractAddress
			break
		} else {
			fmt.Println("please wait ", err)
		}
	}

	time.Sleep(2 * time.Second)
	m.nonceM.setNonce(a.ethAddress, nonce)
	return nil
}

func (m *xenManager) Loop() {
	tasks := make([][]int, m.paraNum)

	for index, _ := range m.worker {
		paraIndex := index % m.paraNum
		tasks[paraIndex] = append(tasks[paraIndex], index)
	}

	for index := 0; index < m.paraNum; index++ {
		fmt.Println("goRoutine", index, "worker", tasks[index])
	}

	fmt.Println("====== begin send xen =======")

	var wg sync.WaitGroup
	for index := 0; index < m.paraNum; index++ {
		index := index
		wg.Add(1)
		go func() {
			m.run(tasks[index])
			wg.Done()
		}()
	}
	wg.Wait()
}

func SignCreateContractTxWithNonce(privateKey *ecdsa.PrivateKey, payLoad []byte, nonce uint64) *types.Transaction {
	tx, err := types.SignTx(types.NewContractCreation(nonce, new(big.Int), gasLimit, gasPrice, payLoad), signer, privateKey)
	panicerr(err)
	return tx
}

func SignTxWithNonce(privateKey *ecdsa.PrivateKey, to common.Address, payLoad []byte, nonce uint64) *types.Transaction {
	tx, err := types.SignTx(types.NewTransaction(nonce, to, new(big.Int), gasLimit, gasPrice, payLoad), signer, privateKey)
	panicerr(err)
	return tx
}

var (
	gasLimit = uint64(20000000)
)

func SendTxs(client *ethclient.Client, txs []*types.Transaction) error {
	for index, v := range txs {
		//time.Sleep(200 * time.Microsecond)
		cnt := 0
		var err error
		for cnt < 10 {
			cnt++
			if e := client.SendTransaction(context.Background(), v); e != nil {
				err = e
				time.Sleep(time.Second * 2)
				if strings.Contains(e.Error(), "mempool is full") || strings.Contains(e.Error(), "number of txs") {
					time.Sleep(20 * time.Second)
				} else if strings.Contains(e.Error(), "failed to replace tx for acccount") {
					err = nil
				} else if strings.Contains(e.Error(), "invalid sequence") {
					time.Sleep(2 * time.Second)
				} else {
					fmt.Println("sendTransaction failed", index, e, "tryCnt", cnt)
				}
			} else {
				err = nil
				break
			}

		}
		if err != nil {
			return err
		}

		if index != 0 && index%200 == 0 {
			fmt.Println("send tx index", index)
		}
	}
	//time.Sleep(2 * time.Second)
	return nil
}
func randomXen() int {
	rand.Seed(time.Now().UnixNano())
	//随机生成100以内的正整数
	return rand.Intn(100)
}

func (m *xenManager) t(workIndex int, txLen int) error {
	a := m.worker[workIndex]
	nonce := m.nonceM.getNonce(a.ethAddress)
	allCnt := int64(0)

	txList := make([]*types.Transaction, 0)
	for index := 0; index < txLen; index++ {

		total := int64(randomXen())
		allCnt += total
		payload, err := coinToolBuilder.Build("t", new(big.Int).SetInt64(total), makeTData(m.xenAddress), new(big.Int).SetInt64(1).Bytes())
		panicerr(err)

		tx := SignTxWithNonce(a.ecdsaPriv, m.coinToolAddress, payload, nonce)
		txList = append(txList, tx)
		nonce++
	}

	if err := SendTxs(m.clientList[workIndex%len(m.clientList)], txList); err != nil {
		fmt.Println("SendTxs failed", err)
		time.Sleep(60 * time.Second)
		m.nonceM.setNonce(a.ethAddress, GetNonce(m.clientList[0], a.ecdsaPriv))
		return err
	}
	time.Sleep(2 * time.Second)
	m.nonceM.setNonce(a.ethAddress, nonce)
	m.xenInfos[workIndex].mintTime += allCnt
	fmt.Println("t succ", workIndex, m.xenInfos[workIndex].string())
	return nil

}
func (m *xenManager) f(workIndex int, txLen int) error {
	a := m.worker[workIndex]
	nonce := m.nonceM.getNonce(a.ethAddress)

	allCnt := 0

	startClaimTime := m.xenInfos[workIndex].claimTime

	txList := make([]*types.Transaction, 0)
	for index := 0; index < txLen; index++ {

		clainIndexList := make([]*big.Int, 0)
		total := randomXen()
		for i := 0; i < total; i++ {
			clainIndexList = append(clainIndexList, new(big.Int).SetInt64(startClaimTime))
			startClaimTime++
		}
		if startClaimTime >= m.xenInfos[workIndex].mintTime {
			break
		}
		allCnt += len(clainIndexList)
		payload, err := coinToolBuilder.Build("f", clainIndexList, makeFData(m.xenAddress, a.ethAddress), new(big.Int).SetInt64(1).Bytes())
		panicerr(err)

		tx := SignTxWithNonce(a.ecdsaPriv, m.coinToolAddress, payload, nonce)
		txList = append(txList, tx)
		nonce++
	}

	if err := SendTxs(m.clientList[workIndex%len(m.clientList)], txList); err != nil {
		fmt.Println("SendTxs failed", err)
		time.Sleep(60 * time.Second)
		m.nonceM.setNonce(a.ethAddress, GetNonce(m.clientList[0], a.ecdsaPriv))
		return err
	}
	time.Sleep(2 * time.Second)
	m.nonceM.setNonce(a.ethAddress, nonce)
	m.xenInfos[workIndex].claimTime += int64(allCnt)
	fmt.Println("f succ", "workIndex", workIndex, m.xenInfos[workIndex].string())
	return nil
}

func (m *xenManager) run(tasks []int) {
	for index, workIndex := range tasks {
		if err := m.t(workIndex, 1); err != nil {
			fmt.Println("init xen failed", err)
		}

		if index%10 == 0 {
			fmt.Println("init xen index", index, "size", len(tasks))
		}

	}

	for true {
		for _, workIndex := range tasks {

			if err := m.t(workIndex, 1); err != nil {
				fmt.Println("send t failed", workIndex, err)
			}

			if err := m.f(workIndex, 1); err != nil {
				fmt.Println("send f failed", workIndex, err)
			}

		}
	}
}
